        "div",
        { cls: "meta" },
        el("div", { cls: "name", text: s.slot === "auto" ? "Sauvegarde rapide" : s.slot }),
        el("div", { cls: "sub", text: `${s.cityName} \xB7 ${s.gameDate} \xB7 ${formatSavedAt(s.savedAt)}` })
