      for (const e of m.edges.values()) ur += e.length * (roadDef(e.type)?.upkeepPerMeterMonth ?? 0);
      $("fin-upkeep-b").textContent = `\u2212${money(ub)} / mois`;
      $("fin-upkeep-r").textContent = `\u2212${money(ur)} / mois`;
