async function getJson(url) {
  try {
    const r = await fetch(url);
    return r.ok ? await r.json() : null;
  } catch {
    return null;
  }
}
async function main() {
  const params = new URLSearchParams(location.search);
  const assetsBase = new URL(params.get("assets") ?? "../../../assets/", location.href);
  const base2 = await getJson(new URL("catalog.json", assetsBase));
  if (!base2) throw new Error("catalogue introuvable");
  const frags = await Promise.all(["catalog.buildings.residential.json", "catalog.buildings.other.json", "catalog.vehicles.json"].map((f) => getJson(new URL(f, assetsBase))));
  const catalog = mergeCatalogs(base2, ...frags.filter((f) => !!f));
  Cache.enabled = true;
  const lib = new AssetLibrary(catalog, assetsBase);
  const mock = new MockSim(catalog, Number(params.get("seed") ?? 7), 4, 2e7, "Clair-Vallon");
  const canvas = document.getElementById("scene");
  const render = initRender(canvas, lib);
  const input = initInput(render.ctx.camera, canvas, (x, z) => render.terrain.heightAt(x, z));
  const ui = initUI({
    onNewGame: () => ui.hideMenu(),
    onNewGameWith: (p2) => {
      ui.hideMenu();
      ui.toast(`D\xE9mo : param\xE8tres re\xE7us (${p2.cityName}, graine ${p2.seed}, ${p2.mapChunks} chunks)`, "info");
    },
    onContinue: () => ui.hideMenu(),
    onSpeed: (speed) => {
      void mock.send("setSpeed", { speed });
    },
    onToggleCamera: () => input.camera.setMode(input.camera.mode === "aerial" ? "street" : "aerial"),
    onSave: () => ui.toast("D\xE9mo : sauvegarde non branch\xE9e (MockSim)", "info"),
    onMenu: () => ui.showMenu({ canContinue: false, inGame: true }),
    onOptions: (o) => applyGraphicsOptions(o, { renderer: render.ctx.renderer, scene: render.ctx.scene, sun: render.ctx.sun, camera: input.camera })
  });
  input.camera.setModeListener((m2) => ui.setCameraMode(m2));
  mock.onSnapshot((s) => {
    render.applySnapshot(s);
    input.camera.bounds = terrainBounds(s.terrain);
    ui.updateStats(s.stats);
    ui.showHud(s.params.cityName);
  });
  mock.onDelta((d) => {
    render.applyDelta(d);
    ui.updateStats(d.stats);
  });
  const cons = initConstruction({ sim: mock, ui, input, scene: render.ctx.scene, models: lib, catalog, heightAt: (x, z) => render.terrain.heightAt(x, z) });
  render.ctx.onFrame.unshift((dt) => {
    input.camera.update(dt);
    const p2 = input.camera.getPose();
    render.env.follow(p2.targetX, p2.targetZ);
    cons.update(dt);
  });
  applyGraphicsOptions(loadOptions(), { renderer: render.ctx.renderer, scene: render.ctx.scene, sun: render.ctx.sun, camera: input.camera });
  mock.start(100);
  const h = mock.heightAt;
  let cx = 0;
  let cz = 0;
  search: for (let r = 0; r < 500; r += 24) for (let a = 0; a < 12; a++) {
    const x = Math.round(Math.cos(a) * r / 8) * 8;
    const z = Math.round(Math.sin(a) * r / 8) * 8;
    let lo = Infinity;
    let hi = -Infinity;
    for (let dx = -120; dx <= 120; dx += 12) for (let dz = -80; dz <= 80; dz += 12) {
      const v2 = h(x + dx, z + dz);
      lo = Math.min(lo, v2);
      hi = Math.max(hi, v2);
    }
    if (lo > mock.terrain.waterLevel + 1.5 && hi - lo < 9) {
      cx = x;
      cz = z;
      break search;
    }
  }
  const tryRoad = (pts, type = "street") => mock.send("buildRoad", { type, points: pts }).catch(() => null);
  await tryRoad([cx - 120, cz, cx + 120, cz], "avenue");
  await tryRoad([cx, cz - 90, cx, cz + 90]);
  const m = cons.machine;
  const place = async (id, x, z) => {
    const a = catalog.assets.find((q2) => q2.id === id);
    if (!a) return;
    const { proposePlacement: proposePlacement2 } = await Promise.resolve().then(() => (init_snapping(), snapping_exports));
    mock.step();
    const p2 = proposePlacement2(cons.mirror, a, x, z, { rot: 0, autoAlign: true });
    await mock.send("placeBuilding", { assetId: id, x: p2.x, z: p2.z, rot: p2.rot, variant: a.variants.length ? Math.floor(Math.random() * a.variants.length) : -1 }).catch(() => null);
  };
  mock.step();
  await place("immeuble_haussmannien", cx - 40, cz + 20);
  await place("maison_pavillon_enduit", cx - 75, cz + 18);
  await place("commerce_cafe_terrasse", cx + 25, cz + 16);
  await place("public_ecole", cx + 60, cz - 30);
  await place("tour_residentielle_balcons", cx - 45, cz - 30);
  await place("maison_chalet_bois", cx + 22, cz + 60);
  mock.step();
  input.camera.setPose({ targetX: cx + 10, targetZ: cz + 10, distance: 230, yaw: 0.7, pitch: 0.75 });
  input.camera.setHome();
  render.ctx.start();
  ui.hideLoading();
  const v = new Vector3();
  window.__demo = {
    mock,
    cons,
    input,
    ui,
    render,
    lib,
    catalog,
    center: { x: cx, z: cz },
    machine: m,
    /** Projection monde -> écran (px CSS). */
    project(x, y, z) {
      v.set(x, y ?? render.terrain.heightAt(x, z), z).project(render.ctx.camera);
      return { x: (v.x + 1) / 2 * canvas.clientWidth, y: (1 - v.y) / 2 * canvas.clientHeight };
    },
    frames: () => render.ctx.frames,
    ready: true
  };
}
main().catch((e) => {
  console.error(e);
  const t = document.getElementById("loading-text");
  if (t) t.textContent = `Erreur : ${e instanceof Error ? e.message : String(e)}`;
  window.__demoError = String(e);
});
